"""Generate src/zeta_rom.v from model/chip_arith.py (scaled twiddles ROM'[k] = ZETAS[k] * 169^-1 mod q).

    python tools/gen_zeta_rom.py
"""
import os
import sys

os.environ["NTT_CHIP"] = "own"          # src/ is this repo's 2-round chip

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "model"))
from chip_arith import ROM_P  # noqa: E402

lines = [
    "// GENERATED by tools/gen_zeta_rom.py from model/chip_arith.py - do not edit by hand.",
    "// Scaled twiddle ROM (team Spec 3): ROM'[k] = 17^BitRev7(k) * 169^-1 mod 3329, 169^-1 = 2285.",
    "// The K-RED multiplier returns 169*a*b, so b * ROM'[k] comes out as b * zeta_k.",
    "",
    "`default_nettype none",
    "",
    "module zeta_rom (",
    "    input  wire [6:0]  idx,",
    "    output reg  [11:0] zeta",
    ");",
    "  always @(*) begin",
    "    case (idx)",
]
lines += [f"      7'd{k:<3}: zeta = 12'd{v};" for k, v in enumerate(ROM_P)]
lines += ["      default: zeta = 12'd0;", "    endcase", "  end", "endmodule", ""]
open(os.path.join(ROOT, "src", "zeta_rom.v"), "w").write("\n".join(lines))
print("wrote src/zeta_rom.v")
